/**
 * Parent/child placement for issues.
 *
 * A root sits at level 0. Nothing may be placed so that it, or any issue
 * already below it, would land deeper than `MAX_SUB_ISSUE_DEPTH`. The links
 * already stored on `issues.parent_id` are the whole tree — this module only
 * judges a placement and walks it.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import type { IssueId } from "@/types/common";
import type { Issue, IssueRollup, IssueStatus } from "@/types/issue";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH}.`,
    );
    this.name = "IssueHierarchyError";
  }
}

export function isOpenStatus(status: IssueStatus): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(status);
}

/** Live and not done or canceled. Archived issues are never open. */
export function isOpenIssue(issue: Issue): boolean {
  return issue.archivedAt === null && isOpenStatus(issue.status);
}

function childrenByParent(
  issues: readonly Issue[],
): ReadonlyMap<string, readonly Issue[]> {
  const grouped = new Map<string, Issue[]>();
  for (const issue of issues) {
    if (issue.parentId === null) continue;
    const bucket = grouped.get(issue.parentId);
    if (bucket === undefined) grouped.set(issue.parentId, [issue]);
    else bucket.push(issue);
  }
  return grouped;
}

function byId(issues: readonly Issue[]): ReadonlyMap<string, Issue> {
  return new Map(issues.map((issue) => [issue.id, issue]));
}

/** Ancestor count. A root is 0. A broken or cyclic link stops the walk. */
export function issueLevel(
  issue: Issue,
  issues: readonly Issue[],
): number {
  const indexed = byId(issues);
  let level = 0;
  let cursor: Issue | undefined = issue;
  const seen = new Set<string>();
  while (cursor?.parentId) {
    if (seen.has(cursor.id)) break;
    seen.add(cursor.id);
    const parent = indexed.get(cursor.parentId);
    if (parent === undefined) break;
    level += 1;
    cursor = parent;
  }
  return level;
}

/** Every issue whose parent chain reaches `issueId`, at any depth. */
export function descendantsOf(
  issueId: IssueId,
  issues: readonly Issue[],
): readonly Issue[] {
  const children = childrenByParent(issues);
  const found: Issue[] = [];
  const seen = new Set<string>();
  const pending = [...(children.get(issueId) ?? [])];
  while (pending.length > 0) {
    const current = pending.pop();
    if (current === undefined || seen.has(current.id)) continue;
    seen.add(current.id);
    found.push(current);
    pending.push(...(children.get(current.id) ?? []));
  }
  return found;
}

/** How many steps down the deepest descendant sits. A leaf is 0. */
function subtreeDepth(issueId: IssueId, issues: readonly Issue[]): number {
  const children = childrenByParent(issues);
  let deepest = 0;
  const pending: { id: string; depth: number }[] = [{ id: issueId, depth: 0 }];
  const seen = new Set<string>([issueId]);
  while (pending.length > 0) {
    const current = pending.pop();
    if (current === undefined) continue;
    if (current.depth > deepest) deepest = current.depth;
    for (const child of children.get(current.id) ?? []) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      pending.push({ id: child.id, depth: current.depth + 1 });
    }
  }
  return deepest;
}

/**
 * Refuses a placement that would loop or push the moved issue's deepest
 * descendant past `MAX_SUB_ISSUE_DEPTH`. `parent` null makes the issue a root.
 * A refused call changes nothing; this function only throws.
 */
export function assertIssuePlacement(
  issue: Issue,
  parent: Issue | null,
  issues: readonly Issue[],
): void {
  if (parent !== null) {
    let cursor: Issue | undefined = parent;
    const indexed = byId(issues);
    const seen = new Set<string>();
    while (cursor !== undefined) {
      if (cursor.id === issue.id) {
        throw new IssueHierarchyError(issue.id, "cycle");
      }
      if (seen.has(cursor.id)) break;
      seen.add(cursor.id);
      cursor =
        cursor.parentId === null ? undefined : indexed.get(cursor.parentId);
    }
  }

  const parentLevel = parent === null ? -1 : issueLevel(parent, issues);
  const landed = parentLevel + 1 + subtreeDepth(issue.id, issues);
  if (landed > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issue.id, "too_deep");
  }
}

/** Depth check for an issue that does not exist yet, so it has no descendants. */
export function assertNewIssueDepth(
  parent: Issue,
  issues: readonly Issue[],
): void {
  if (issueLevel(parent, issues) + 1 > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(parent.id, "too_deep");
  }
}

export function rollupOf(
  issueId: IssueId,
  issues: readonly Issue[],
): IssueRollup {
  let open = 0;
  let closed = 0;
  for (const descendant of descendantsOf(issueId, issues)) {
    if (descendant.archivedAt !== null) continue;
    if (isOpenStatus(descendant.status)) open += 1;
    else closed += 1;
  }
  return { total: open + closed, open, closed };
}

/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/**
 * Deepest level an issue may occupy. A root is level 0, so a chain may contain
 * at most this many parent links.
 */
export const MAX_SUB_ISSUE_DEPTH: number = 3;

