/** Every issue in the org, archived included. Hierarchy walks use this. */
export async function listAllIssues(orgId: OrgId): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(orgPredicate(issues.orgId, orgId))
    .all();
  return rows.map((row) => toIssue(row));
}

/**
 * Direct sub-issues that are still live, oldest first: creation time, then
 * the per-project issue number.
 */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.parentId, parentId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Archives each live id. Rows already archived are left untouched. */
export async function archiveLiveIssues(
  orgId: OrgId,
