/**
 * Places `issueId` under `parentId`, or makes it a root when `parentId` is
 * null. The issues already below it keep their parent links and move with it.
 * Announces `issue.updated` with `changedFields: ["parentId"]`.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (issue.parentId === input.parentId) return issue;

  const existing = await issueRepo.listAllIssues(input.orgId);
  const parent =
    input.parentId === null
      ? null
      : requireSameProjectParent(existing, input.parentId, issue.projectId);
  if (parent !== null) assertNotArchived("Issue", parent.id, parent);
  assertIssuePlacement(issue, parent, existing);

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct live sub-issues, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issueId);
}

/** Counts of every non-archived issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const existing = await issueRepo.listAllIssues(orgId);
  return rollupOf(issueId, existing);
}

/**
 * The parent must be a live issue of the same project. Another project, or an
 * id this workspace does not have, is not found — the caller learns nothing
 * about the other row.
 */
function requireSameProjectParent(
  issues: readonly Issue[],
  parentId: IssueId,
  projectId: ProjectId,
): Issue {
  const parent = issues.find((candidate) => candidate.id === parentId);
  if (parent === undefined || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/**
 * When `child` has just stopped being open, tell its direct parent's assignee
 * once if nothing open remains anywhere below that parent. Preferences and
 * the "never tell the actor" rule live in `notify`.
 */
async function notifyParentIfSubIssuesCompleted(
  actor: Actor,
  child: Issue,
): Promise<void> {
  if (child.parentId === null) return;

  const existing = await issueRepo.listAllIssues(child.orgId);
  const parent = existing.find((candidate) => candidate.id === child.parentId);
  if (parent === undefined) return;
  if (parent.archivedAt !== null || parent.assigneeId === null) return;

  const stillOpen = descendantsOf(parent.id, existing).some((descendant) =>
    isOpenIssue(descendant),
  );
  if (stillOpen) return;

  await notify(parent.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `Every sub-issue under ${parent.title} is closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}

